SNB_st.name='SNB'; 
SNB_st.lat=47.0541;
SNB_st.lon=12.9577;
SNB_st.alt=3106;
SNB_st.env='Mt';
SNB_st.footp='Mx';
%%
SNB_rd=read_ebas_merged_STN('C:\github_trend\raw_data\merged_Sonnblick (2).nc', SNB_st);

names_rd=fieldnames(SNB_rd);

%%
datevec(SNB_rd.Time(1)) %data since 2013 %[output:8d5d9cf2]
datevec(SNB_rd.Time(end)) % 2025 %[output:4e34a620]
 prctile(SNB_rd.U370_S,[5 50 95]) % no RH given, but inlet heated , time with RH< 26% --> don0t compute dry %[output:24cd41ee]
% 20°C --> ok as at JFJ
% % prctile(SNB_rd.U1_S11,[5 50 95])
plotFigControl(SNB_rd,SNB_st.name);
%%
% adapt names for (2)make data ok with wavelength change

SNB_rd.Properties.VariableNames{2}='BbsG_S';
SNB_rd.Properties.VariableNames{5}='BsG_S';


SNB_rd.Properties.VariableNames{10}='Ba3_A';
SNB_rd.Properties.VariableNames{14}='Ba7_A';

% change in 1.1.2016

SNB_rd.BbsR_S=SNB_rd.BbsReco_S;
SNB_rd.BsR_S=SNB_rd.BsReco_S;

P8=timerange('2013-01-01','2016-01-01');
P9=timerange('2016-01-01','2026-01-01');

SNB_rd.BbsR_S(P8)=SNB_rd.BbsB_S(P8);
SNB_rd.BsR_S(P8)=SNB_rd.BsB_S(P8);

SNB_rd.BbsB_S(P8)=SNB_rd.BbsReco_S(P8);
SNB_rd.BsB_S(P8)=SNB_rd.BsReco_S(P8);

SNB_rd.BbsReco_S=[];
SNB_rd.BsReco_S=[];


%%
% BP detection for scat coef and backscat

names_sc={'BsB_S', 'BsG_S', 'BsR_S'};
break_SNB_scat_BP=change_point_analysis_Def(SNB_rd,names_sc,0.05,'SNB','scattering'); %[output:15b500f9] %[output:96081c03] %[output:2ac75d81] %[output:5cfe4630]
T_SNB_scat_BP=make_table_breakpoints_def(break_SNB_scat_BP);

names_bsc={'BbsB_S', 'BbsG_S', 'BbsR_S'};
break_SNB_bscat_BP=change_point_analysis_Def(SNB_rd,names_bsc,0.05,'SNB','Backscattering'); %[output:5caf2fb0] %[output:7014c4c4] %[output:86a64491] %[output:4e5ac798]
T_SNB_bscat_BP=make_table_breakpoints_def(break_SNB_bscat_BP);
%%
% BP detection for abs
names_abs={'Ba1_A', 'Ba2_A', 'Ba3_A','Ba4_A','Ba5_A','Ba6_A','Ba7_A'};
break_SNB_abs_BP=change_point_analysis_Def(SNB_rd,names_abs,0.05,'SNB','Absorption'); %[output:70a824b2] %[output:23f562e2] %[output:0cd05f1a] %[output:13eaeb69] %[output:92f94342] %[output:3cf9bddd]
T_SNB_abs_BP=make_table_breakpoints_def(break_SNB_abs_BP);
%%
% remove _dry
N=names_rd(endsWith(names_rd,'_dry'));
for i=1:length(N)
    SNB_rd.(N{i})=[];
end
names_rd=fieldnames(SNB_rd);
%%
lambdaSC=[450;525;635];
lambdaAE=[370;470;520;590;660;880;950];
SNB_cal=compute_exp_SSA(SNB_rd,lambdaSC, lambdaAE); %[output:7580ef2f] %[output:2e5e9496] %[output:62ee7d36] %[output:22019bbe] %[output:1df0edf1] %[output:8cdb5455] %[output:63444d0d] %[output:33903b39] %[output:8a820c7a] %[output:840e5767] %[output:8c7e1e37] %[output:46b630e1] %[output:3bb5d264] %[output:5994b61c] %[output:9315d47e] %[output:55fa58d3] %[output:2b8bbebb] %[output:6ebba5c3] %[output:9b630640] %[output:3ad01871] %[output:790dc1bc] %[output:3c33117c] %[output:1acb9e73] %[output:79638969] %[output:336f3040] %[output:34c019fd] %[output:50cd9629] %[output:31ce53b3] %[output:470493ba] %[output:785875a1] %[output:41968bb1] %[output:3ccfbecf] %[output:63d87fc4] %[output:4072cfaf] %[output:85527981] %[output:73c3a89f] %[output:4efb8f82] %[output:25f5f3a5] %[output:01338664] %[output:4461f758] %[output:081a073c] %[output:7213b0b9] %[output:2b2eac7e] %[output:3268d77d] %[output:3f4c0527] %[output:1b3e1775] %[output:82fa9e58] %[output:3a6bf3c2] %[output:70f4cd6d] %[output:2b8eae88] %[output:8d8f2838] %[output:75e9ba30] %[output:86dd3a06] %[output:13968f56] %[output:74d1a26f] %[output:31edc712] %[output:4f958661] %[output:4d2a64f1] %[output:92a7568b] %[output:164c6599] %[output:5a341d37] %[output:6df16589] %[output:5ce735dc]
plotFigControl_cal(SNB_cal,SNB_st.name); %[output:36a9ba41] %[output:814a032c] %[output:9ed3c97c]
%%
% BP detection for expS, Backscat fraction, expA and SSA

names_exps={'expS_bg3', 'expS_br3', 'expS_gr3'};
break_SNB_exps_BP=change_point_analysis_Def(SNB_cal,names_exps,0.05,'SNB','scattering exp'); %[output:267db0e3] %[output:0e3cff04] %[output:0e92a826] %[output:99da959e]
T_SNB_exps_BP=make_table_breakpoints_def(break_SNB_exps_BP); %[output:12b4eb66] %[output:822d2f23] %[output:9f954f10] %[output:09a15fc9] %[output:3f104ecb] %[output:785e6531] %[output:511f6255] %[output:8bc01bae] %[output:808f9252] %[output:2b683cae] %[output:381adc59] %[output:6b5a104c] %[output:87db5f0c] %[output:4c274e13] %[output:1c3b889b] %[output:0a4c9ebe] %[output:02012460] %[output:45199e05]

names_BbF={'BbsFG'};
break_SNB_BbF_BP=change_point_analysis_Def(SNB_cal,names_BbF,0.05,'SNB','backscat fraction'); %[output:6a85448e] %[output:6ab79f78]
T_SNB_BbF_BP=make_table_breakpoints_def(break_SNB_BbF_BP); %[output:891f614f]

names_expA={'expA_fit'};
break_SNB_expA_BP=change_point_analysis_Def(SNB_cal,names_expA,0.05,'SNB','Absorption exp'); %[output:419ef90e] %[output:28c27d2a]
T_SNB_expA_BP=make_table_breakpoints_def(break_SNB_expA_BP);

names_SSA={'SSA311'};
break_SNB_SSA_BP=change_point_analysis_Def(SNB_cal,names_SSA,0.05,'SNB','SSA'); %[output:3162023c] %[output:7b0b10ce]
T_SNB_SSA_BP=make_table_breakpoints_def(break_SNB_SSA_BP); %[output:714dd19e] %[output:8ea42ff0]
%%
SNB_tr=SNB_rd;
SNB_tr.y=year(SNB_tr.Time);
SNB_tr=outerjoin(SNB_tr, SNB_cal);
%scat + backscat  trend on G  only:
SNB_tr.BsB_S=[];
SNB_tr.BsR_S=[]; %[output:632f330e]
%%
SNB_tr.BbsB_S=[];
SNB_tr.BbsR_S=[];

% compute trend only on AE 520
SNB_tr.Ba1_A=[];
SNB_tr.Ba2_A=[];
SNB_tr.Ba4_A=[];
SNB_tr.Ba5_A=[];
SNB_tr.Ba6_A=[];
SNB_tr.Ba7_A=[];

%expS  trend on BG and expA fit from AE33 only:
SNB_tr.expS_br3=[];
SNB_tr.expS_gr3=[];
% compute only expA_fit
SNB_tr.expA_bg=[];
SNB_tr.expA_gr=[];
SNB_tr.expA_br=[];
names=fieldnames(SNB_tr);

%%
[SNB_result_MK,SNB_result_LMSlog,SNB_result_LMSlin]=all_trend_STN(SNB_tr,SNB_st); %[output:953645a8] %[output:6e19ab6e] %[output:78f7081b] %[output:6f9500bb] %[output:029a43f6] %[output:880455c8] %[output:8b877c97] %[output:32da3621] %[output:26a0582a] %[output:4ce19f4d] %[output:554655b0] %[output:891c78f0] %[output:9ed8bbe4] %[output:71f6ddf0] %[output:6838607c] %[output:05e93b32] %[output:1a6f35cc] %[output:8f43056b] %[output:87b1681f] %[output:698b3897] %[output:58aa72eb] %[output:5ae7a6f7] %[output:62e8ed86] %[output:45f4712f] %[output:821e8118] %[output:4bab5ea8] %[output:2eff82f4] %[output:39abaa9e] %[output:487beb35] %[output:2297187c] %[output:6a44de14] %[output:8a052a01] %[output:3751bc55] %[output:2bdc242f] %[output:76ffa0a3] %[output:7f5326e7] %[output:9948865f] %[output:62ef6b62] %[output:452f5c49] %[output:9dda0049] %[output:12287937] %[output:58249922] %[output:44847fb1] %[output:9f5a462e] %[output:19544b59] %[output:53807370] %[output:893aeda5] %[output:5b04a33e] %[output:4dfa58fa] %[output:22aee707] %[output:7cf1518b] %[output:4c8ee7e9] %[output:1b56476f] %[output:214c9c10] %[output:899c92cf] %[output:651f913c] %[output:650b5b31] %[output:870a5d99] %[output:1a97229b] %[output:1b7434a2] %[output:349c17db] %[output:30d7efdc] %[output:2f2e1e88] %[output:42ffdf04] %[output:0f28a09d] %[output:2ea9e796] %[output:44eb1cdd] %[output:17c9047f] %[output:0345d5cd] %[output:92d2985c] %[output:9f6c36e8] %[output:5d1f57f0] %[output:2f66463c]

writetable(SNB_result_MK,'SNB_res_MK.txt'); %, 'delimiter',',' )
